    h, w = len(grid), len(grid[0])
    div = next(v for v in grid[0] if v)
    row_divs = [r for r in range(h) if all(v == div for v in grid[r])]
    col_divs = [c for c in range(w) if all(grid[r][c] == div for r in range(h))]
    row_starts = [0] + [r + 1 for r in row_divs]
    row_ends = row_divs + [h]
    col_starts = [0] + [c + 1 for c in col_divs]
    col_ends = col_divs + [w]
    panel_h, panel_w = row_ends[0], col_ends[0]

    # A panel outside the palette column contains the stencil; preserve its
    # local placement and copy it into each panel, recolored by row key.
    candidates = []
    for r0, r1 in zip(row_starts, row_ends):
        for c0, c1 in list(zip(col_starts, col_ends))[1:]:
            mask = [[grid[r0+i][c0+j] not in (0, div) for j in range(panel_w)]
                    for i in range(panel_h)]
            count = sum(sum(row) for row in mask)
            if count:
                candidates.append((count, mask))
    template = max(candidates, key=lambda item: item[0])[1]

    out = [row[:] for row in grid]
    for r0, r1 in zip(row_starts, row_ends):
        key = next((grid[r][c] for r in range(r0, r1)
                    for c in range(col_ends[0]) if grid[r][c] not in (0, div)), 0)
        for c0, c1 in zip(col_starts, col_ends):
            for i in range(panel_h):
                for j in range(panel_w):
                    out[r0+i][c0+j] = key if template[i][j] else 0
    for r in row_divs:
        out[r] = [div] * w
    for c in col_divs:
        for r in range(h):
            out[r][c] = div
    return out
